<?php
require_once __DIR__.'/B19ReplayIdentityMariaDbPipelineTest.php';
use App\Application\MarketData\Services\MarketDataEvidenceExportService;
use App\Infrastructure\Persistence\MarketData\EodCorrectionRepository;
use Illuminate\Support\Facades\DB;

/** One real world: new batch proof plus affected E021 admission revalidation, no golden regeneration. */
class B19MultiFamilyMariaDbPipelineTest extends B19ReplayIdentityMariaDbPipelineTest
{
    private $batchDirs=[];
    private $batchExpectedBindings;
    public function test_all_identity_paths_follow_independent_inputs_and_persisted_publication_binding(): void {parent::test_all_identity_paths_follow_independent_inputs_and_persisted_publication_binding();}
    protected function tearDown(): void {foreach($this->batchDirs as $dir)if(is_dir($dir)){foreach(glob($dir.'/*') as $f)if(is_file($f))unlink($f);rmdir($dir);}parent::tearDown();}
    private function batchDir(): string {$d=sys_get_temp_dir().'/b19_batch_'.uniqid();$this->batchDirs[]=$d;return $d;}
    private function captureDir($dir,$name): void {
        $index=json_decode(file_get_contents($dir.'/artifact_manifest.json'),true);$this->assertSame('Asia/Jakarta',$index['timestamp_context']['platform_timezone']);foreach($index['files'] as $file=>$meta){$this->assertNotEmpty($meta['binding_refs']);foreach($meta['binding_refs'] as $ref){$side=substr($ref,strlen('#/binding_contexts/'));$this->assertArrayHasKey($side,$index['binding_contexts']);}}
        if(in_array($name,['match','run_success','correction_unchanged'],true))foreach($index['binding_contexts'] as $side=>$context){$this->assertSame('COMPLETE',$context['status'],$name.' '.$side.' complete independently sourced bindings');foreach($this->batchExpectedBindings as $field=>$value)$this->assertSame($value,$context['bindings'][$field]['value'],$field.' authoritative pre-replay input');$reasons=$context['bindings']['reason_codes']['value'];$ordered=$reasons;sort($ordered,SORT_STRING);$this->assertSame($ordered,$reasons);}
foreach($index['files'] as $file=>$meta)$this->assertSame(hash_file('sha256',$dir.'/'.$file),$meta['sha256']);
        if(!getenv('B19_COMPLETION_ARTIFACT_DIR'))return;$to=getenv('B19_COMPLETION_ARTIFACT_DIR').'/batch_'.$name;if(!is_dir($to))mkdir($to,0775,true);foreach(glob($dir.'/*') as $f)if(is_file($f))copy($f,$to.'/'.basename($f));
        if(is_file($dir.'/replay_result.json')){$r=json_decode(file_get_contents($dir.'/replay_result.json'),true);file_put_contents($to.'/persisted_metric.json',json_encode(DB::table('md_replay_daily_metrics')->where('replay_id',$r['replay_id'])->where('trade_date',$r['trade_date'])->first(),JSON_PRETTY_PRINT));}
    }
    private function pack($replay,$date,$name): array {$d=$this->batchDir();app(MarketDataEvidenceExportService::class)->exportReplayEvidence($replay,$date,$d);$p=json_decode(file_get_contents($d.'/replay_evidence_pack.json'),true);$this->captureDir($d,$name);return $p;}
    protected function prepareArtifactBindings(array $expected,array $oracle,array $navigation,$temporal): array {
        $fields=['observation_manifest_hash','config_registry_revision','factor_set_hash','price_product_code','price_product_version','canonicalization_version','formula_version','read_model_version','trade_date_requested','trade_date_effective','readiness_state','freshness_state'];
        $v=array_intersect_key($oracle['payload'],array_flip($fields));
        $v['run_id']=$navigation['run_id'];$v['publication_id']=$navigation['publication_id'];$v['publication_manifest_hash']=$oracle['publication_manifest_hash'];$v['config_snapshot_id']=$navigation['config_snapshot_id'];$v['config_snapshot_hash']=$oracle['payload']['config_content_hash'];$v['temporal_revision_set_hash']=$temporal;$v['factor_set_id']=$navigation['factor_set_id'];
        $expected['expected_artifact_semantic_bindings']=$v;return $expected;
    }
    protected function afterIdentityRun($verifier,$runId,$fixture,$publicationId,$date,array $expected,array $manifest,array $files,array $world,$replay): void
    {
        $this->batchExpectedBindings=$expected['expected_artifact_semantic_bindings'];
        $exporter=app(MarketDataEvidenceExportService::class);$baseline=DB::table('md_replay_daily_metrics')->where('replay_id',$replay)->where('trade_date',$date)->first();$p=$this->pack($baseline->replay_id,$date,'match');
        $this->assertSame('PASS',$p['replay_result']['replay_status']);$this->assertSame('VERIFIED',$p['evidence_admission']['identity_verification']['status']);$this->assertSame('ADMITTED_COMPLETE',$p['evidence_admission']['evidence_admission_state']);
        foreach([$p['replay_result']['coverage'],$p['replay_result']['expected_coverage']] as $coverage)foreach(['coverage_gate_state'=>'PASS','coverage_ratio'=>1,'coverage_min_threshold'=>0.98,'expected_bar_count'=>1,'available_bar_count'=>1,'missing_bar_count'=>0,'coverage_reason_code'=>'COVERAGE_THRESHOLD_MET'] as $key=>$value)$this->assertSame($value,$coverage[$key],$key.' authoritative real world');
        $dir=$this->batchDir();$result=$exporter->exportRunEvidence($runId,$dir);$summary=json_decode(file_get_contents($dir.'/run_summary.json'),true);$publication=json_decode(file_get_contents($dir.'/publication_manifest.json'),true);$events=json_decode(file_get_contents($dir.'/run_event_summary.json'),true);
        $this->assertSame($runId,$summary['run_id']);$this->assertSame('SUCCESS',$summary['terminal_status']);$this->assertSame('READABLE',$summary['publishability_state']);$this->assertSame($date,$summary['trade_date_requested']);$this->assertSame($publicationId,$publication['publication_id']);$this->assertSame('SEALED',$publication['seal_state']);
        $oracle=json_decode(file_get_contents(__DIR__.'/../../fixtures/replay/r0025-synthetic-v2-candidate-v5/expected/expected_publication_manifest.json'),true);$this->assertSame($oracle['publication_manifest_hash'],$publication['publication_manifest_hash']);
        foreach(['run_summary.json','publication_manifest.json','run_event_summary.json','eligibility_export.csv','invalid_bars_export.csv','anomaly_report.md'] as $file)$this->assertGreaterThan(0,filesize($dir.'/'.$file));
        $this->assertSame($runId,$events['run_id']);$this->assertSame((int)DB::table('eod_run_events')->where('run_id',$runId)->count(),array_sum($events['stage_counts']));
        $rows=array_map('str_getcsv',file($dir.'/eligibility_export.csv',FILE_IGNORE_NEW_LINES));$this->assertCount(2,$rows);$this->assertContains('ELIG_INSUFFICIENT_HISTORY',$rows[1]);
        $telemetry=json_decode(file_get_contents($dir.'/source_attempt_telemetry.json'),true);$this->assertSame($runId,(int)DB::table('eod_run_events')->where('event_id',$telemetry['event_id'])->value('run_id'));$this->assertSame(1,(int)$telemetry['attempt_count']);$this->assertSame(200,(int)$telemetry['final_http_status']);$this->assertSame('yahoo_finance',$telemetry['provider']);$this->assertStringContainsString('SUCCESS',file_get_contents($dir.'/anomaly_report.md'));$this->captureDir($dir,'run_success');
        foreach(['HELD','FAILED'] as $status){$rid=DB::table('eod_runs')->insertGetId(['trade_date_requested'=>$date,'source'=>'api','terminal_status'=>$status,'publishability_state'=>'NOT_READABLE','created_at'=>$date.' 17:00:00','started_at'=>$date.' 17:00:00','updated_at'=>$date.' 17:00:00']);$d=$this->batchDir();$exporter->exportRunEvidence($rid,$d);$r=json_decode(file_get_contents($d.'/run_summary.json'),true);$this->assertSame($rid,$r['run_id']);$this->assertSame($status,$r['terminal_status']);$this->assertSame('NOT_READABLE',$r['publishability_state']);$this->assertFileDoesNotExist($d.'/publication_manifest.json');$this->assertStringContainsString($status,file_get_contents($d.'/anomaly_report.md'));$this->captureDir($d,'run_'.strtolower($status));}
        // An unverified publication digest must not produce a complete companion.
        $manifestDigest=DB::table('eod_publications')->where('publication_id',$publicationId)->value('publication_manifest_hash');
        try {DB::table('eod_publications')->where('publication_id',$publicationId)->update(['publication_manifest_hash'=>str_repeat('0',64)]);$badDir=$this->batchDir();$exporter->exportRunEvidence($runId,$badDir);$bad=json_decode(file_get_contents($badDir.'/artifact_manifest.json'),true);$this->assertSame('INCOMPLETE',$bad['binding_contexts']['actual']['status'],'unverified manifest cannot be admitted as complete V2 binding');}
        finally {DB::table('eod_publications')->where('publication_id',$publicationId)->update(['publication_manifest_hash'=>$manifestDigest]);}
        // Each drift input is an independent counterfactual fixture version, never output-derived.
        foreach(['bars_batch_hash'=>'canonical','indicators_batch_hash'=>'indicator','eligibility_batch_hash'=>'eligibility'] as $field=>$layer){$probe=$expected;$probe['expected_artifact_context'][$field]=hash('sha256','b19 independent '.$layer.' drift v1');$this->writeProbe($fixture,$probe,$manifest,$files,'b19-'.$layer.'-drift-v1');$metric=$verifier->verifyRunAgainstFixture($runId,$fixture,null,$publicationId);$q=$this->pack($metric['replay_id'],$date,$layer);$matches=array_values(array_filter($q['replay_result']['mismatches'],function($m)use($field){return $m['field']===$field;}));$this->assertCount(1,$matches);$this->assertSame($probe['expected_artifact_context'][$field],$matches[0]['expected']);$this->assertSame($expected['expected_artifact_context'][$field],$matches[0]['actual']);$this->assertSame('REPLAY_ARTIFACT_HASH_MISMATCH',$matches[0]['reason_code']);$this->assertSame('MISMATCH',$q['replay_result']['comparison_result']);$this->assertSame($layer==='canonical'?'bars_only':($layer==='indicator'?'indicators_only':'eligibility_only'),$q['replay_result']['artifact_changed_scope']);}
        $probe=$expected;$probe['expected_bound_input_context']['serialization_version']='independent-format-v2';$this->writeProbe($fixture,$probe,$manifest,$files,'b19-format-drift-v1');$metric=$verifier->verifyRunAgainstFixture($runId,$fixture,null,$publicationId);$q=$this->pack($metric['replay_id'],$date,'formatting');$this->assertNotSame('PASS',$q['replay_result']['replay_status']);$this->assertStringContainsString('serialization',json_encode($q['replay_result']['mismatches']));
        $probe=$expected;$probe['expected_coverage_context']['coverage_expected_count']=4;$probe['expected_coverage_context']['expected_bar_count']=4;$probe['expected_coverage_context']['coverage_available_count']=2;$probe['expected_coverage_context']['available_bar_count']=2;$probe['expected_coverage_context']['coverage_missing_count']=2;$probe['expected_coverage_context']['missing_bar_count']=2;$probe['expected_coverage_context']['coverage_ratio']=0.5;$probe['expected_coverage_context']['coverage_min_threshold']=0.9;$probe['expected_coverage_context']['coverage_gate_state']='BLOCKED';$probe['expected_coverage_context']['coverage_reason_code']='RUN_COVERAGE_NOT_EVALUABLE';$this->writeProbe($fixture,$probe,$manifest,$files,'b19-coverage-divergence-v1');$metric=$verifier->verifyRunAgainstFixture($runId,$fixture,null,$publicationId);$q=$this->pack($metric['replay_id'],$date,'coverage');foreach(['coverage_gate_state'=>'NOT_EVALUABLE','coverage_ratio'=>0.5,'coverage_min_threshold'=>0.9,'expected_bar_count'=>4,'available_bar_count'=>2,'missing_bar_count'=>2,'coverage_reason_code'=>'RUN_COVERAGE_NOT_EVALUABLE'] as $key=>$value)$this->assertSame($value,$q['expected_state']['coverage'][$key]);$this->assertSame('BLOCKED',$q['expected_state']['expected_context']['expected_coverage_context']['legacy_coverage_gate_state_raw']);$this->assertSame(1,$q['actual_state']['coverage']['expected_bar_count']);$this->assertSame('MISMATCH',$q['replay_result']['comparison_result']);
        // Unsupported RAW cannot turn immutable observations into a verified publication capability.
        $beforeProduct=DB::table('eod_publications')->where('publication_id',$publicationId)->value('price_product_code');
        try {DB::table('eod_publications')->where('publication_id',$publicationId)->update(['price_product_code'=>'RAW']);$this->writeProbe($fixture,$expected,$manifest,$files,'b19-unsupported-raw-v1');$raw=$verifier->verifyRunAgainstFixture($runId,$fixture,null,$publicationId);$this->assertSame('BLOCKED',$raw['replay_status']);$this->assertSame('UNAVAILABLE',$raw['actual_context']['actual_publication_manifest_identity']['applicability']);}
        finally {DB::table('eod_publications')->where('publication_id',$publicationId)->update(['price_product_code'=>$beforeProduct]);}
        // Actual repository request/approval and actual unchanged correction pipeline.
        $repo=new EodCorrectionRepository();$corr=$repo->createRequest($date,'DATASET_HASH_CREATED','Independent unchanged-correction artifact probe','b19-proof',$publicationId,$runId);$repo->approve($corr->correction_id,'b19-proof');$correctionRun=$world['pipeline']->runDaily($date,'api',$corr->correction_id);$state=$repo->findById($corr->correction_id);$this->assertContains($state->status,['CONSUMED_CURRENT','CANCELLED']);
        $d=$this->batchDir();$exporter->exportCorrectionEvidence($corr->correction_id,$d);$c=json_decode(file_get_contents($d.'/correction_evidence.json'),true);$this->assertSame('UNCHANGED',$c['changed_decision']);$this->assertSame('NOT_RESEALED_UNCHANGED',$c['reseal_status']);$this->assertFalse($c['publication_switch']);$this->assertNull($c['new_publication']);$this->assertSame($publicationId,$c['prior_publication']['publication_id']);$this->captureDir($d,'correction_unchanged');
        $this->writeProbe($fixture,$expected,$manifest,$files,'b19-correction-replay-v1');$metric=$verifier->verifyRunAgainstFixture($correctionRun->run_id,$fixture,null,$publicationId);$q=$this->pack($metric['replay_id'],$date,'correction_replay');$this->assertSame('NOT_RESEALED_UNCHANGED',$q['replay_result']['correction_lifecycle']['actual']['correction_reseal_status']);$this->assertFalse($q['replay_result']['correction_lifecycle']['actual']['correction_publication_switch']);
