    }
    private function writeProbe($dir,array $probe,array $manifest,array $files,$version): void { $files['expected_replay_result.json']=$probe;$files['expected_hashes.json']=array_intersect_key($probe['expected_artifact_context'],array_flip(['bars_batch_hash','indicators_batch_hash','eligibility_batch_hash']));foreach($files as $name=>$body)file_put_contents($dir.'/expected/'.$name,json_encode($body,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));$manifest['fixture_version']=$version;foreach($manifest['files'] as $name)$manifest['files_sha256'][$name]=hash_file('sha256',$dir.'/'.$name);file_put_contents($dir.'/manifest.json',json_encode($manifest));}
}
